        Set<Integer> seen = new HashSet<>();
        return numbers.stream()
                .filter(n -> !seen.add(n))
                .distinct()
                .collect(Collectors.toList());
    }

    public static void main(String[] args) {
        List<Integer> numbers = Arrays.asList(1, 2, 3, 2, 4, 1);
