public class Main {
    static int removeDuplicates(int[] numbers) {
        if (numbers.length == 0) return 0;
        int write = 1;
        for (int read = 1; read < numbers.length; read++) {
            if (numbers[read] != numbers[write - 1]) numbers[write++] = numbers[read];
        }
        return write;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 1, 2, 2, 3};
        int length = removeDuplicates(numbers);
        System.out.println("New length: " + length);
        System.out.println("Unique values: " + Arrays.toString(Arrays.copyOf(numbers, length)));
    }
}

