public class Main {
    static class LRUCache<K, V> extends LinkedHashMap<K, V> {
        private final int capacity;
        LRUCache(int capacity) {
            super(capacity, 0.75f, true);
            this.capacity = capacity;
        }
        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > capacity;
        }
    }

    public static void main(String[] args) {
        LRUCache<Integer, String> cache = new LRUCache<>(2);
        cache.put(1, "A");
        cache.put(2, "B");
        System.out.println("Get 1: " + cache.get(1));
        cache.put(3, "C");
        System.out.println("Cache after adding 3: " + cache);
        System.out.println("Key 2 exists: " + cache.containsKey(2));
    }
}

import java.util.*;

public class Main {
    static List<Integer> topKFrequent(int[] numbers, int k) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int n : numbers) frequency.merge(n, 1, Integer::sum);

        PriorityQueue<Map.Entry<Integer, Integer>> heap =
                new PriorityQueue<>(Comparator.comparingInt(Map.Entry::getValue));
        for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            heap.offer(entry);
            if (heap.size() > k) heap.poll();
        }

        List<Integer> result = new ArrayList<>();
        while (!heap.isEmpty()) result.add(heap.poll().getKey());
        Collections.reverse(result);
        return result;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 1, 1, 2, 2, 3};
        System.out.println("Top 2: " + topKFrequent(numbers, 2));
    }
}

